#include <stdio.h>
#include <stdlib.h>

int main() {
    float a, d, n;

    printf("Enter the first term: ");
    if (scanf("%f", &a) != 1) {
        printf("Invalid input.\n");
        return 1;
    }

    printf("Enter the common difference: ");
    if (scanf("%f", &d) != 1) {
        printf("Invalid input.\n");
        return 1;
    }

    printf("Enter the value of N: ");
    if (scanf("%f", &n) != 1 || n < 1) {
        printf("Invalid input.\n");
        return 1;
    }

    float sum = (n / 2) * (2 * a + (n - 1) * d);

    printf("The sum of the first %g terms is %g.\n", n, sum);

    return 0;
}
```

